#!/bin/bash
VIDEO_B64=""
cleanup() { tput cnorm; kill $LOAD_PID 2>/dev/null; clear; exit; }
trap cleanup SIGINT SIGTERM
if ! command -v brotli &> /dev/null; then
    echo "Error: brotli not found. Please install it."
    exit 1
fi
show_loading() {
    tput civis
    while true; do
        for i in "." ".." "..."; do
            echo -ne "\rLoading$i   "
            sleep 0.3
        done
    done
}
show_loading &
LOAD_PID=$!
RAW_DECODED=$(echo "$VIDEO_B64" | base64 -d | brotli -d)
RAW_ESCAPED=$(printf "%b" "$RAW_DECODED")
IFS=$'\x03' read -d '' -ra FRAMES <<< "$RAW_ESCAPED"
kill $LOAD_PID
wait $LOAD_PID 2>/dev/null
clear
while true; do
    for frame in "${FRAMES[@]}"; do
        [[ -z "$frame" ]] && continue
        echo -ne "$frame"
        sleep 0.0500
    done
done
